156	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setRegistrationDate(registrationDate);
160	        owner.setHouseholdId(householdId);
161	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
162	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
163	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
164	        this.clinicService.saveOwner(owner);
165	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
166	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        currentOwner.setAddress(ownerFieldsDto.getAddress());
181	        currentOwner.setCity(ownerFieldsDto.getCity());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
185	        normalizeEmail(ownerFieldsDto);
186	        currentOwner.setEmail(ownerFieldsDto.getEmail());
187	        currentOwner.setHouseholdId(
188	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
189	        this.clinicService.saveOwner(currentOwner);
190	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Transactional
195	    @Override
196	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
197	        Owner owner = this.clinicService.findOwnerById(ownerId);
198	        if (owner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        this.clinicService.deleteOwner(owner);
202	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner == null) {
210	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	        }
212	        HttpHeaders headers = new HttpHeaders();
213	        Pet pet = petMapper.toPet(petFieldsDto);
214	        owner.setId(ownerId);
215	        pet.setOwner(owner);
216	        pet.getType().setName(null);
217	        this.clinicService.savePet(pet);
218	        PetDto petDto = petMapper.toPetDto(pet);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
220	            .buildAndExpand(pet.getId()).toUri());
221	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
227	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
228	        if (currentOwner != null) {
229	            Pet currentPet = this.clinicService.findPetById(petId);
230	            if (currentPet != null) {
231	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
232	                currentPet.setName(petFieldsDto.getName());
233	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
234	                this.clinicService.savePet(currentPet);
235	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
244	        HttpHeaders headers = new HttpHeaders();
245	        Visit visit = visitMapper.toVisit(visitFieldsDto);
246	        Pet pet = new Pet();
247	        pet.setId(petId);
248	        visit.setPet(pet);
249	        this.clinicService.saveVisit(visit);
250	        VisitDto visitDto = visitMapper.toVisitDto(visit);
251	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
252	            .buildAndExpand(visit.getId()).toUri());
253	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
254	    }
255	
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
260	        Owner owner = this.clinicService.findOwnerById(ownerId);
261	        if (owner != null) {
262	            Pet pet = owner.getPet(petId);
263	            if (pet != null) {
264	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
265	            }
266	        }
267	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
268	    }
269	
270	    /**
271	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
272	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
273	     * the request body already rejects null and empty values, but permits whitespace-only strings
274	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
275	     * that gap so every required field must carry a non-blank value.
276	     *
277	     * @param ownerFieldsDto the submitted owner fields
278	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
279	     */
280	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
281	        List<String> missing = new ArrayList<>();
282	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
283	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
284	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
285	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
286	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
287	        if (!missing.isEmpty()) {
288	            throw new InvalidOwnerFieldsException(missing);
289	        }
290	    }
291	
292	    /**
293	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
294	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
295	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
296	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
297	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
298	     * {@link PostcodeValidator}.
299	     *
300	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
301	     *                       {@link #rejectBlankOwnerFields} having already run)
302	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
303	     */
304	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
305	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
306	            throw new InvalidOwnerFieldsException(List.of("postcode"));
307	        }
308	    }
309	
310	    private void addIfBlank(List<String> missing, String fieldName, String value) {
311	        if (value == null || value.isBlank()) {
312	            missing.add(fieldName);
313	        }
314	    }
315	
316	    /**
317	     * Normalizes the submitted {@code address} on create to its canonical form (see
318	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
319	     * stored and returned, and the form every later address comparison (the required-field check,
320	     * household duplicate detection and the shared household id) is judged on. A null address is left
321	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
322	     * after normalization likewise reduces to the empty string and is rejected there.
323	     *
324	     * @param ownerFieldsDto the submitted owner fields
325	     */
326	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
327	        String address = ownerFieldsDto.getAddress();
328	        if (address == null) {
329	            return;
330	        }
331	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
332	    }
333	
334	    /**
335	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
336	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
337	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
338	     * {@code 400 Bad Request}.
339	     *
340	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
341	     *                       {@link #rejectBlankOwnerFields} having already run)
342	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
343	     */
344	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
345	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
346	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
347	        ownerFieldsDto.setTelephone(normalized);
348	    }
349	
350	    /**
351	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
352	     * untouched (email is optional). When present it is reduced to its canonical form (see
353	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
354	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
355	     *
356	     * @param ownerFieldsDto the submitted owner fields
357	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
358	     */
359	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
360	        String email = ownerFieldsDto.getEmail();
361	        if (email == null || email.isBlank()) {
362	            return;
363	        }
364	        String normalized = EmailNormalizer.normalize(email)
365	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
366	        ownerFieldsDto.setEmail(normalized);
367	    }
368	
369	    /**
370	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
371	     * duplicate detection is now expressed through the single derived {@code identityKey}
372	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
373	     * which replaces the previously separate telephone, email and household checks. Two owners denote
374	     * the same person when their identities collide on the telephone - the identity's distinguishing
375	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
376	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
377	     * same household with different telephones have different identities and are both allowed; an email
378	     * or a household on its own no longer makes a duplicate.
379	     *
380	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
381	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
382	     * @param householdId    the household id derived for the owner being created (see
383	     *                       {@link HouseholdNormalizer#toHouseholdId})
384	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
385	     */
386	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
387	        String identityKey = OwnerIdentity.identityKey(
388	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
389	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
390	        boolean inUse = this.clinicService.findAllOwners().stream()
391	            .map(Owner::getTelephone)
392	            .filter(Objects::nonNull)
393	            .map(TelephoneNormalizer::toComparisonKey)
394	            .anyMatch(telephoneKey::equals);
395	        if (inUse) {
396	            throw new DuplicateOwnerIdentityException(identityKey);
397	        }
398	    }
399	
400	    /**
401	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
402	     * both match the submitted values, compared case-insensitively. The count reflects only owners
403	     * already persisted at the time of the create, so the owner being created is never included.
404	     *
405	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
406	     *                  having already run)
407	     * @param lastName  the submitted last name (non-blank here)
408	     * @return the number of existing owners sharing the same first and last name
409	     */
410	    private int countNamesakes(String firstName, String lastName) {
411	        return (int) this.clinicService.findAllOwners().stream()
412	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
413	                && lastName.equalsIgnoreCase(owner.getLastName()))
414	            .count();
415	    }
416	
417	    /**
418	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
419	     * whose stored {@code householdId} equals the value derived for the owner being created. The
420	     * count reflects only owners already persisted at the time of the create, so the owner being
421	     * created is never included; callers add one to obtain the household size after this create.
422	     *
423	     * @param householdId the household identifier derived for the owner being created (see
424	     *                    {@link HouseholdNormalizer#toHouseholdId})
425	     * @return the number of existing owners already sharing that household
426	     */
427	    private int countHouseholdMembers(String householdId) {
428	        if (householdId == null) {
429	            return 0;
430	        }
431	        return (int) this.clinicService.findAllOwners().stream()
432	            .map(Owner::getHouseholdId)
433	            .filter(householdId::equals)
434	            .count();
435	    }
436	
437	    /**
438	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
439	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
440	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
441	     *
442	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
443	     *             run)
444	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
445	     */
446	    private void rejectCityAtCapacity(String city) {
447	        long ownersInCity = this.clinicService.findAllOwners().stream()
448	            .map(Owner::getCity)
449	            .filter(Objects::nonNull)
450	            .filter(city::equalsIgnoreCase)
451	            .count();
452	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
453	            throw new OwnerCityAtCapacityException(city);
454	        }
455	    }
456	
457	    /**
458	     * Resolves the effective registration date for a create, rolled onto a business day. The
459	     * supplied date is used when present, otherwise the server's current date; either way the result
460	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
461	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
462	     * stored {@code registrationDate}, the membership number's year segment and the daily
463	     * create-limit's per-day count - is judged on this adjusted date.
464	     *
465	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
466	     *                                 default to the server's current date
467	     * @return the effective registration date, guaranteed to fall on a business day
468	     */
469	    /**
470	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
471	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
472	     * adjustment; a future date cannot describe a registration that has already happened, so it is
473	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
474	     * server's current date) and any date on or before today are accepted.
475	     *
476	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
477	     *                                 omitted
478	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
479	     */
480	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
481	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
482	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
483	        }
484	    }
485	
486	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
487	        LocalDate registrationDate =
488	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
489	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
490	    }
491	
492	    /**
493	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
494	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
495	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
496	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
497	     * Too Many Requests}.
498	     *
499	     * @param registrationDate   the create's effective registration date, already rolled onto a
500	     *                           business day by {@link #effectiveRegistrationDate}
501	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
502	     *                           {@code registrationDate} equals {@code registrationDate}
503	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
504	     *                                              owner registrations
505	     */
506	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
507	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
508	            throw new OwnerDailyRegistrationLimitException(registrationDate);
509	        }
510	    }
511	
512	    /**
513	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
514	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
515	     * bulk-signup warning are judged on.
516	     *
517	     * @param registrationDate the create's effective registration date, already rolled onto a business
518	     *                         day by {@link #effectiveRegistrationDate}
519	     * @return the number of existing owners registered on that day
520	     */
521	    private long countRegisteredOn(LocalDate registrationDate) {
522	        return this.clinicService.findAllOwners().stream()
523	            .map(Owner::getRegistrationDate)
524	            .filter(registrationDate::equals)
525	            .count();
526	    }
527	}
